import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const AddComplaint = () => {
  const [complaint, setComplaint] = useState({
    residentId: '',
    description: '',
    status: 'Pending',
  });
  const [residents, setResidents] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetchResidents();
  }, []);

  const fetchResidents = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/residents');
      setResidents(response.data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleChange = (e) => {
    setComplaint({ ...complaint, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5000/api/complaints', complaint);
      navigate('/complaints');
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Add Complaint</h2>
      <select name="residentId" value={complaint.residentId} onChange={handleChange} required>
        <option value="">Select Resident</option>
        {residents.map((resident) => (
          <option key={resident._id} value={resident._id}>
            {resident.name}
          </option>
        ))}
      </select>
      <textarea
        name="description"
        placeholder="Complaint Description"
        value={complaint.description}
        onChange={handleChange}
        required
      />
      <select name="status" value={complaint.status} onChange={handleChange}>
        <option value="Pending">Pending</option>
        <option value="Resolved">Resolved</option>
      </select>
      <button type="submit" className="submit-btn">
        Add Complaint
      </button>
    </form>
  );
};

export default AddComplaint;
